#include<bits/stdc++.h>
using namespace std;using U=uint64_t;struct Edge{int from,to,goal,a,h,lo,hi,mo,c,mi[5];U k,v,f,cl,r;};
int main(int ac,char**av){ifstream in(av[1]);int n,np,ne,F,cap;in>>n>>np>>ne>>F>>cap;int sid;U sk,sv;in>>sid>>sk>>sv;assert(sk==((1ULL<<n)-1));vector<Edge>E(ne);vector<vector<int>>adj(np);for(int i=0;i<ne;i++){auto&t=E[i];in>>t.from>>t.to>>t.k>>t.v>>t.f>>t.cl>>t.r>>t.goal>>t.a>>t.h>>t.lo>>t.hi>>t.mo>>t.c;for(int&x:t.mi)in>>x;adj[t.from].push_back(i);}assert(in);U limit=ac>2?stoull(av[2]):2000000;int nr=cap-F+1; __uint128_t universe=np; universe<<=n; for(int j=0;j<5;j++)universe*=nr; assert(universe<=((__uint128_t)UINT64_MAX)+1);auto enc=[&](int p,U color,array<int,5>Q){U z=p;z=(z<<n)|color;for(int q:Q){assert(q>=F&&q<=cap);z=z*nr+q-F;}return z;};auto dec=[&](U z,int&p,U&col,array<int,5>&Q){for(int j=4;j>=0;j--){Q[j]=z%nr+F;z/=nr;}col=z&((1ULL<<n)-1);p=z>>n;};vector<U>states;vector<uint32_t>prev,edge;unordered_map<U,uint32_t>idx;idx.reserve(limit*1.3);auto add=[&](U z,uint32_t p,int ei){if(idx.count(z))return;idx[z]=states.size();states.push_back(z);prev.push_back(p);edge.push_back(ei);};array<int,5>Qi;Qi.fill(F);add(enc(sid,sv,Qi),UINT32_MAX,-1);U next=1;int dep=0;for(uint32_t si=0;si<states.size();si++){if(si==next){dep++;next=states.size();cerr<<"layer "<<dep<<" states "<<states.size()<<"\n";}int p;U color;array<int,5>Q;dec(states[si],p,color,Q);for(int ei:adj[p]){auto&t=E[ei];if((color&t.k)!=t.v)continue;int hi=t.hi;for(int j=0;j<5;j++)if(t.mi[j]>-900)hi=min(hi,Q[j]-t.mi[j]);hi-=((hi-t.h)%2+2)%2;if(hi<t.lo)continue;if(t.goal){cout<<"status WITNESS depth "<<dep+1<<" states "<<states.size()<<"\n";vector<uint32_t>path;uint32_t u=si;while(u!=UINT32_MAX){path.push_back(u);u=prev[u];}reverse(path.begin(),path.end());cout<<"word";for(auto s:path)if(edge[s]!=UINT32_MAX)cout<<" "<<E[edge[s]].a;cout<<" "<<t.a<<"\n";for(auto s:path){int pp;U cc;array<int,5>qq;dec(states[s],pp,cc,qq);cout<<pp<<" "<<cc<<" "<<edge[s];for(int x:qq)cout<<" "<<x;cout<<"\n";}cout<<"goal_edge "<<ei<<" source_height "<<hi<<"\n";return 0;}U color2=((color^t.f)&~t.cl)|t.r;int topout=hi+t.mo;vector<int>maxes;if(t.lo<=min(hi,Q[0]-t.mo)){int q=min(hi,Q[0]-t.mo);q-=((q-t.h)%2+2)%2;if(q>=t.lo)maxes.push_back(Q[0]);}int lo=max(t.lo,Q[0]-t.mo+1);lo+=((t.h-lo)%2+2)%2;for(int q=lo;q<=hi;q+=2)maxes.push_back(q+t.mo);for(int mx:maxes){array<int,5>Q2;for(int j=0;j<5;j++)Q2[j]=j<=t.c?mx:Q[j-t.c];add(enc(t.to,color2,Q2),si,ei);if(states.size()>=limit){cout<<"status CAP states "<<states.size()<<" depth "<<dep<<"\n";return 0;}}}}cout<<"status EXHAUSTED states "<<states.size()<<" depth "<<dep<<"\n";}
